REF.update({k: ref for k, _, ref, _, _ in (x for x in SCEN if x[0] != 'lead')})


def build(out):
    b = Doc(chap=3, layout=LAYOUT, ref=REF)
    b.px_full = 2496  # ширина снимка блока во всю страницу браузера (1248 px при масштабе 2)
    b.h1(3, 'Тестирование, проверка работоспособности и анализ полученных результатов')

    b.text('Тестирование программного средства проводилось в два этапа. На первом этапе выполнялись программные тесты, то есть автоматические тесты, которые вызывают функции, сервисы и программный интерфейс приложения и сравнивают результат с ожидаемым. На втором этапе проверялась бизнес-логика через пользовательский интерфейс: от имени гостя, клиента и сотрудников банка выполнялись операции с ошибочными данными и операции, нарушающие правила банка, и проверялось, как система на них реагирует.')
    b.text('Программные тесты написаны с использованием тестового фреймворка Vitest и проверяют сервисы бизнес-логики, в которых сосредоточены денежные расчёты. Часть тестов проверяет отдельные функции без базы данных, например расчёт графика платежей по кредиту, скоринговую оценку заявки, округление денежных сумм, контрольные цифры IBAN и коды двухфакторной защиты. Остальные тесты вызывают сервисы с настоящей базой данных MySQL и проверяют получившиеся проводки, остатки счетов и статусы документов.')
    b.text('Для тестов используется отдельная база данных talerbank_test. Перед запуском она удаляется и создаётся заново из тех же SQL-скриптов, что и рабочая база, поэтому тесты проверяют настоящую схему со всеми ограничениями, внешними ключами и триггерами, а рабочие данные не затрагиваются. Каждый тест сам создаёт нужных ему клиентов и счета и не зависит от результатов других тестов.')
    b.unit('run', [
        'Всего написано 30 тестов, сгруппированных по сервисам, и все они запускаются одной командой npm test.',
        'Все тесты завершаются успешно. Тесты сервиса двойной записи подтверждают, что остаток счёта всегда равен оборотам по проводкам, списание сверх остатка не оставляет в базе никаких следов, повторный запрос с тем же ключом не создаёт второй операции, а параллельные переводы с одного счёта не уводят его в минус. Проводки нельзя изменить или удалить даже прямым запросом к базе данных, а ошибочная операция отменяется сторнированием, при котором исходные проводки сохраняются.',
        'Тесты сервиса переводов проверяют конвертацию по курсу банка со спредом, отказ при совпадающих или чужих счетах, неверном номере счёта, нехватке денег и превышении суточного лимита, а также подтверждение крупного перевода кодом, который после трёх неверных попыток аннулируется. Тесты кредитного модуля сверяют аннуитетный и дифференцированный графики с формулами и проверяют решения скоринга, в том числе отказ при долговой нагрузке выше 40 %. Тесты вкладов проверяют начисление процентов с учётом високосного года и досрочное закрытие с перерасчётом по ставке до востребования.',
    ], 'fig-test-run.png', 'Результат запуска программных тестов')

    b.text('Тесты бизнес-логики выполнялись в браузере на демонстрационных данных при ширине окна 1280 пикселей, что соответствует экрану ноутбука. Для банковской системы важно не только правильно выполнять операции, но и правильно отказывать в них, поэтому проверялись ошибки пользователя при заполнении форм, нарушения бизнес-правил, отказы в доступе и исключительные ситуации. Каждая ошибка должна обнаруживаться до изменения данных, объясняться понятным сообщением рядом с полем, к которому она относится, и не приводить к потере уже введённых данных.')
    for item in SCEN[1:]:
        if item[0] == 'lead':
            b.text(item[1])
            continue
        key, before, _, after, caption = item
        b.unit(key, [before, after], f'fig-test-{key}.png', caption)

    b.text('Во время тестирования были найдены и исправлены несколько дефектов. Большая часть из них проявлялась только при одновременных запросах, например две заявки на перевод, созданные до подтверждения, вместе превышали суточный лимит, а одновременные решения «одобрить» и «отклонить» по одному подозрительному переводу срабатывали оба. Тесты бизнес-логики в интерфейсе выявили непонятное сообщение при превышении частоты попыток входа и вывод долговой нагрузки с десятичной точкой. Найденные дефекты исправлены, а сценарии, в которых они проявлялись, повторно проверены.')
    note = b.text('[Дополнить после проверки в Яндекс Браузере, Firefox и Opera на Windows: версии браузеров и рисунок со страницей в каждом из них.]')
    for run in note.runs:
        run.font.highlight_color = WD_COLOR_INDEX.YELLOW
    b.text('Таким образом, все программные тесты и тесты бизнес-логики завершились ожидаемым результатом. Программное средство выполняет бизнес-операции, указанные в требованиях, сохраняет целостность денежных данных при одновременной работе пользователей, обнаруживает ошибки пользователя до изменения данных и сообщает о них понятным образом.')

    b.save(out)

if __name__ == '__main__':
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(KURS, 'razdel-3.docx')
    build(out)
    print(out)
